from lib import *
S = SS('w8')
steps = [
    step("同样的 UDP 载荷发给四种目的地,在 en0 上抓包,帧的目的 MAC 随目的 IP 的类型变化:单播发给默认网关 → 目的 MAC 是网关的网卡地址(70:85:6c:…);子网定向广播(网段最后一个地址)→ ff:ff:ff:ff:ff:ff;受限广播 255.255.255.255 → ff:ff:ff:ff:ff:ff;组播 239.1.2.3 → 01:00:5e:… 。每个帧都是 50 字节。组播 MAC 的构造规则:01:00:5e 加上 IP 地址低 23 位——239.1.2.3 的低 23 位是 0x010203,所以 MAC 是 01:00:5e:01:02:03;高位被丢掉,239.129.2.3 也会映射到同一个 MAC。", t=tl(S(1)), mark=lidx(S(1), '子网定向广播', '受限广播', '组播 239.1.2.3'), done=lidx(S(1), '单播(发给默认网关)', '低 23 位'), b=bars([['单播 → 网关 MAC', 1, 'MAC=网关'], ['子网广播 → ff:ff…', 2, 'MAC=广播'], ['受限广播 → ff:ff…', 2, 'MAC=广播'], ['组播 → 01:00:5e…', 3, 'MAC=组播']], 3, mark=[1, 2, 3], done=[0]), kv=KV([['单播', '目的 MAC = 下一跳的 MAC'], ['广播', '目的 MAC = ff:ff:ff:ff:ff:ff'], ['组播', '01:00:5e + IP 低 23 位']], ['组播'])),
    step("谁会收到?本机内部两个套接字绑定同一个端口(SO_REUSEPORT),发 3 个数据报:单播 127.0.0.1,接收者 A 收 3 个、B 收 0 个——单播只交给其中一个套接字;受限广播 255.255.255.255,A 和 B 各收 3 个;组播 224.9.9.9(两个都加入了该组),A 和 B 各收 3 个。广播和组播会交给所有符合条件的套接字,单播只交给一个。", t=tl(S(2)), mark=lidx(S(2), '受限广播', '组播 224.9.9.9'), done=lidx(S(2), '单播 127.0.0.1', '单播只会交给'), b=bars([['单播:A 收到', 3, '3'], ['单播:B 收到', 0, '0'], ['广播:B 收到', 3, '3'], ['组播:B 收到', 3, '3']], 3, mark=[2, 3], done=[0, 1]), kv=KV([['单播', '只交给一个套接字'], ['广播 / 组播', '交给所有符合条件的套接字'], ['组播前提', '套接字必须加入该组']], ['单播'])),
    step("ping 子网广播地址(网段最后一个地址):抓到 2 个发往广播地址的 ICMP 请求帧,目的 MAC 都是 ff:ff:ff:ff:ff:ff——网络层的“广播地址”对应链路层的“广播 MAC”。本机的 net.inet.icmp.bmcastecho=1,也就是系统会回应广播的 echo;结果 ping 只发了 2 个请求,却收到 2 个应答外加 +50 个重复应答——网段里有 50 多台主机都回了话,往返时间从 0.165 ms 到 1103.209 ms 不等。这就是广播 ping 能放大流量(smurf 攻击)的原因。路由器不会转发子网定向广播和受限广播(这是规范和经验,本机无法实验)。", t=tl(S(3)), mark=lidx(S(3), 'ping 输出末几行', '抓到发往网段广播'), done=lidx(S(3), 'sysctl net.inet.icmp'), b=bars([['发出的请求', 2, '2 个'], ['收到的应答(含重复)', 52, '2 + 50 个']], 52, mark=[1], done=[0]), kv=KV([['bmcastecho=1', '会回应广播 echo'], ['2 个请求', '换来 52 个应答'], ['路由器', '不转发广播(规范,未实测)']], ['2 个请求'])),
    step("这个网段上 30 秒内三种目的 MAC 的帧:单播 6406 个(78.9%,4849737 字节,主要是本机自己的流量),广播 789 个(9.7%),组播 926 个(11.4%)。广播加组播共 1715 个帧,约每秒 57.2 个——网段里每台主机的网卡都要收下并交给系统看一眼,哪怕与自己无关。这就是为什么广播域不能无限大:主机越多,每个人被迫处理的无关广播越多。", t=tl(S(4)), mark=lidx(S(4), '广播 + 组播'), done=lidx(S(4), '单播:', '广播:', '组播:'), b=bars([['单播', 6406, '6406'], ['广播', 789, '789'], ['组播', 926, '926']], 6406, mark=[1, 2], done=[0]), kv=KV([['广播 + 组播', '约 57 帧/秒'], ['单播', '78.9% 的帧'], ['代价', '每台主机都要处理无关的广播']], ['代价'])),
]
A = mkartw('w8', 8, '网络协议,单播,广播,组播,MAC地址,UDP,真实验证,动画演示',
    '同一个 UDP 载荷发给单播 / 子网广播 / 255.255.255.255 / 组播,目的 MAC 分别是网关的、ff:ff:ff:ff:ff:ff、ff:ff:ff:ff:ff:ff、01:00:5e:…(IP 低 23 位);两个套接字绑同一端口时单播只交给 1 个、广播和组播交给全部;ping 广播地址 2 个请求换来 52 个应答;网段里 30 秒有 789 个广播帧、926 个组播帧。',
    '同一个包发给“一个人”“网段所有人”“一组人”,在网线上有什么不同?目的 MAC 怎么由 IP 地址决定?谁会收到?广播 ping 为什么会放大流量?这篇用抓包和一组本机套接字实验一一验证。',
    [('01:00:5e + 低 23 位', 'IPv4 组播地址映射到以太网组播 MAC 的规则'), ('2 → 52', 'ping 子网广播地址:2 个请求换来的应答数(含 50 个重复)'), ('57 帧/秒', '这个网段上广播加组播的帧速率(30 秒 1715 个)')],
    [('三种目的', '<p>目的 IP 决定目的 MAC:单播用下一跳的 MAC,广播用 ff:ff:ff:ff:ff:ff,组播用 01:00:5e 加 IP 低 23 位。</p>'),
     ('谁收到', '<p>单播只交给一个套接字,广播交给所有套接字,组播交给所有加入了该组的套接字。</p>'),
     ('广播 ping', '<p>目的地址是子网广播地址的 ping 会让网段里所有愿意回应的主机都回一个应答,2 个请求得到了 52 个应答,这是放大攻击的原理。</p>'),
     ('广播的代价', '<p>每个广播和组播帧都会被网段里每台主机的网卡收下,所以广播域越大,无关流量越多。</p>')],
    steps,
    [ENV_W + '。第一节在 en0 上抓包;第二节用本机 127.0.0.1 与 255.255.255.255 的套接字做实验,组播接口选 lo0;第三节会向本网段发一次广播 ping(只发了 3 个,实际只发出 2 个请求就收到大量应答);第四节统计整个网段 30 秒的帧,对别人的流量只做数量统计;MAC 只保留前 3 字节',
     '没有验证:路由器是否转发广播(规范是不转发,没实测);IGMP 如何管理组播成员(见 IGMP 两篇);交换机的组播泛洪 / IGMP snooping;IPv6 没有广播、用组播替代(见 NDP 一篇);广播风暴;Wi-Fi 下广播以最低速率发送带来的影响'],
    '单播广播组播')
